1	import 'dart:async';
2	
3	import 'package:flutter_test/flutter_test.dart';
4	import 'package:fpdart/fpdart.dart';
5	
6	import 'package:cerne/core/failure/failure.dart';
7	import 'package:cerne/core/resource.dart';
8	import 'package:cerne/features/entries/domain/entities/entries_page.dart';
9	import 'package:cerne/features/entries/domain/entities/entry.dart';
10	import 'package:cerne/features/entries/domain/repositories/entries_repository.dart';
11	import 'package:cerne/features/entries/presentation/cubit/entries_search_cubit.dart';
12	
13	Entry _entry(String id) => Entry(
14	  id: id,
15	  content: 'content-$id',
16	  source: EntrySource.manual,
17	  chatMessageId: null,
18	  occurredAt: '2026-01-01T00:00:00Z',
19	  serverRevision: 1,
20	  createdAt: '2026-01-01T00:00:00Z',
21	  updatedAt: '2026-01-01T00:00:00Z',
22	);
23	
24	/// A plain (non-mocktail) fake — same convention
25	/// `meus_registros_cubit_test.dart`'s own fakes use. Needed here because
26	/// several tests (debounce coalescing, stale-result discarding) must
27	/// assert exactly how many times/with what argument `search()` was
28	/// called, and the stale-result tests need to resolve two calls out of
29	/// order — a single static mocktail stub can't express that naturally.
30	class _FakeEntriesRepository implements EntriesRepository {
31	  final List<Either<Failure, List<Entry>>> _results = [];
32	  final List<Completer<Either<Failure, List<Entry>>>> _completers = [];
33	  final List<String> searchCalls = [];
34	
35	  /// spec-5-3 — every `source`/`dateFrom`/`dateTo` [search] was called
36	  /// with, in order; `updateFilters()`'s own tests below read this to
37	  /// assert what the cubit actually forwarded.
38	  final List<({EntrySource? source, DateTime? dateFrom, DateTime? dateTo})>
39	  searchFilterCalls = [];
40	
41	  /// When `true`, [search] returns a `Completer`-backed future the test
42	  /// resolves explicitly (via [resolve]) rather than immediately returning
43	  /// a queued result — needed to reproduce a stale in-flight call landing
44	  /// after a newer one has already superseded it.
45	  bool gated = false;
46	
47	  void queueSearch(Either<Failure, List<Entry>> result) {
48	    _results.add(result);
49	  }
50	
51	  void resolve(int callIndex, Either<Failure, List<Entry>> result) {
52	    _completers[callIndex].complete(result);
53	  }
54	
55	  @override
56	  Future<Either<Failure, List<Entry>>> search(
57	    String query, {
58	    EntrySource? source,
59	    DateTime? dateFrom,
60	    DateTime? dateTo,
61	  }) {
62	    searchCalls.add(query);
63	    searchFilterCalls.add((source: source, dateFrom: dateFrom, dateTo: dateTo));
64	    if (gated) {
65	      final completer = Completer<Either<Failure, List<Entry>>>();
66	      _completers.add(completer);
67	      return completer.future;
68	    }
69	    if (_results.isEmpty) {
70	      throw StateError(
71	        'no queued search() result for call #${searchCalls.length}',
72	      );
73	    }
74	    return Future.value(_results.removeAt(0));
75	  }
76	
77	  @override
78	  Future<Either<Failure, Entry>> create({
79	    required String content,
80	    required EntrySource source,
81	    int? mediaDurationSeconds,
82	    String? chatMessageId,
83	  }) async => throw UnimplementedError('not expected to be called');
84	
85	  @override
86	  Future<Either<Failure, EntriesPage>> list({
87	    String? cursor,
88	    int limit = 20,
89	    EntrySource? source,
90	    DateTime? dateFrom,
91	    DateTime? dateTo,
92	  }) async => throw UnimplementedError('not expected to be called');
93	
94	  @override
95	  Future<Either<Failure, Entry>> getById(String id) async =>
96	      throw UnimplementedError('not expected to be called');
97	
98	  // Story 8.4 — not exercised by this suite, same trivial rationale
99	  // create()/list()/getById() above already follow.
100	  @override
101	  Future<Either<Failure, Unit>> clearLocalCache() async => right(unit);
102	}
103	
104	/// Collects every state the cubit emits for the duration of [act] — same
105	/// helper/rationale `auth_cubit_test.dart` already documents: this stack
106	/// has no `bloc_test` pin, so this drives [EntriesSearchCubit] through its
107	/// public API only, the same way any other `flutter_bloc` consumer would.
108	Future<List<Resource<List<Entry>>>> _emittedDuring(
109	  EntriesSearchCubit cubit,
110	  FutureOr<void> Function() act,
111	) async {
112	  final emitted = <Resource<List<Entry>>>[];
113	  final subscription = cubit.stream.listen(emitted.add);
114	  await act();
115	  await subscription.cancel();
116	  return emitted;
117	}
118	
119	void main() {
120	  late _FakeEntriesRepository fakeRepository;
121	  late EntriesSearchCubit cubit;
122	
123	  setUp(() {
124	    fakeRepository = _FakeEntriesRepository();
125	    cubit = EntriesSearchCubit(fakeRepository);
126	  });
127	
128	  tearDown(() async {
129	    if (!cubit.isClosed) {
130	      await cubit.close();
131	    }
132	  });
133	
134	  test('starts as ResourceIdle', () {
135	    expect(cubit.state, const ResourceIdle<List<Entry>>());
136	  });
137	
138	  test('I/O matrix: "Semantic match" — a successful search emits '
139	      'ResourceLoading then ResourceData with the repository\'s results, '
140	      '300ms after the triggering call', () async {
141	    fakeRepository.queueSearch(right([_entry('e1')]));
142	
143	    final emitted = await _emittedDuring(cubit, () async {
144	      cubit.onQueryChanged('ansiedade');
145	      await Future<void>.delayed(const Duration(milliseconds: 350));
146	    });
147	
148	    expect(emitted, [
149	      // Not a `const` comparison (Review finding) — `_search()`
150	      // deliberately emits a fresh, non-canonicalized `ResourceLoading`
151	      // each time, so only its runtime type is asserted here.
152	      isA<ResourceLoading<List<Entry>>>(),
153	      isA<ResourceData<List<Entry>>>().having(
154	        (s) => s.data.map((e) => e.id),
155	        'data ids',
156	        ['e1'],
157	      ),
158	    ]);
159	  });
160	
161	  test('onQueryChanged trims the raw input before calling search()', () async {
162	    fakeRepository.queueSearch(right([_entry('e1')]));
163	
164	    cubit.onQueryChanged('  ansiedade  ');
165	    await Future<void>.delayed(const Duration(milliseconds: 350));
166	
167	    expect(fakeRepository.searchCalls, ['ansiedade']);
168	  });
169	
170	  test('I/O matrix: "Rapid typing" — 5 keystrokes within 300ms fire exactly '
171	      'one entries-search call, for the final value', () async {
172	    fakeRepository.queueSearch(right([_entry('e1')]));
173	
174	    cubit.onQueryChanged('a');
175	    await Future<void>.delayed(const Duration(milliseconds: 50));
176	    cubit.onQueryChanged('an');
177	    await Future<void>.delayed(const Duration(milliseconds: 50));
178	    cubit.onQueryChanged('ans');
179	    await Future<void>.delayed(const Duration(milliseconds: 50));
180	    cubit.onQueryChanged('ansi');
181	    await Future<void>.delayed(const Duration(milliseconds: 50));
182	    cubit.onQueryChanged('ansiedade');
183	
184	    // Still well within the 300ms window since the last keystroke — no
185	    // call should have fired yet.
186	    await Future<void>.delayed(const Duration(milliseconds: 100));
187	    expect(fakeRepository.searchCalls, isEmpty);
188	
189	    // Past the 300ms debounce window from the final keystroke.
190	    await Future<void>.delayed(const Duration(milliseconds: 250));
191	    expect(fakeRepository.searchCalls, ['ansiedade']);
192	  });
193	
194	  test('I/O matrix: "Query cleared" — a non-empty query followed by an empty/'
195	      'whitespace one cancels the pending timer and emits ResourceIdle, '
196	      'with no request ever firing', () async {
197	    final emitted = await _emittedDuring(cubit, () async {
198	      cubit.onQueryChanged('ansiedade');
199	      cubit.onQueryChanged('   ');
200	      await Future<void>.delayed(const Duration(milliseconds: 350));
201	    });
202	
203	    expect(emitted, [const ResourceIdle<List<Entry>>()]);
204	    expect(fakeRepository.searchCalls, isEmpty);
205	  });
206	
207	  test('I/O matrix: "Offline" — a Failure.networkOffline from the repository '
208	      'emits ResourceError(networkOffline), never a cache fallback', () async {
209	    fakeRepository.queueSearch(
210	      left(const Failure.networkOffline(message: 'Sem conexão')),
211	    );
212	
213	    final emitted = await _emittedDuring(cubit, () async {
214	      cubit.onQueryChanged('ansiedade');
215	      await Future<void>.delayed(const Duration(milliseconds: 350));
216	    });
217	
218	    expect(emitted, [
219	      isA<ResourceLoading<List<Entry>>>(),
220	      isA<ResourceError<List<Entry>>>().having(
221	        (s) => s.failure,
222	        'failure',
223	        isA<NetworkOffline>(),
224	      ),
225	    ]);
226	  });
227	
228	  test('Review finding: recovers from ResourceError — a failed search '
229	      'followed by a new query re-arms the debounce and reaches '
230	      'ResourceData normally, rather than getting stuck in error', () async {
231	    fakeRepository.queueSearch(
232	      left(const Failure.networkOffline(message: 'Sem conexão')),
233	    );
234	    fakeRepository.queueSearch(right([_entry('e1')]));
235	
236	    final emitted = await _emittedDuring(cubit, () async {
237	      cubit.onQueryChanged('ansiedade');
238	      await Future<void>.delayed(const Duration(milliseconds: 350));
239	      cubit.onQueryChanged('nervosismo');
240	      await Future<void>.delayed(const Duration(milliseconds: 350));
241	    });
242	
243	    expect(emitted, [
244	      isA<ResourceLoading<List<Entry>>>(),
245	      isA<ResourceError<List<Entry>>>(),
246	      isA<ResourceLoading<List<Entry>>>(),
247	      isA<ResourceData<List<Entry>>>().having(
248	        (s) => s.data.map((e) => e.id),
249	        'data ids',
250	        ['e1'],
251	      ),
252	    ]);
253	    expect(fakeRepository.searchCalls, ['ansiedade', 'nervosismo']);
254	  });
255	
256	  test(
257	    'I/O matrix: "Stale response" — query A in flight, query B supersedes '
258	    'it; A\'s result is discarded on arrival (generation mismatch)',
259	    () async {
260	      fakeRepository.gated = true;
261	
262	      cubit.onQueryChanged('query-a');
263	      await Future<void>.delayed(const Duration(milliseconds: 350));
264	      expect(fakeRepository.searchCalls, ['query-a']);
265	      expect(cubit.state, isA<ResourceLoading<List<Entry>>>());
266	
267	      cubit.onQueryChanged('query-b');
268	      await Future<void>.delayed(const Duration(milliseconds: 350));
269	      expect(fakeRepository.searchCalls, ['query-a', 'query-b']);
270	
271	      // Query A's (stale) result resolves after query B has already
272	      // started — must never land.
273	      fakeRepository.resolve(0, right([_entry('stale')]));
274	      await Future<void>.delayed(Duration.zero);
275	      expect(cubit.state, isA<ResourceLoading<List<Entry>>>());
276	
277	      // Query B's own result still lands normally.
278	      fakeRepository.resolve(1, right([_entry('fresh')]));
279	      await Future<void>.delayed(Duration.zero);
280	      expect((cubit.state as ResourceData<List<Entry>>).data.map((e) => e.id), [
281	        'fresh',
282	      ]);
283	    },
284	  );
285	
286	  test('Review finding: two back-to-back in-flight searches each emit their '
287	      'own distinct ResourceLoading on the stream — a canonicalized const '
288	      'instance would make the second transition a no-op (Cubit.emit skips '
289	      're-emitting a state == the current one), which would in turn leave '
290	      'MeusRegistrosScreen\'s own skeleton timer un-reset for the second '
291	      'query', () async {
292	    fakeRepository.gated = true;
293	
294	    final emitted = await _emittedDuring(cubit, () async {
295	      cubit.onQueryChanged('query-a');
296	      await Future<void>.delayed(const Duration(milliseconds: 350));
297	      cubit.onQueryChanged('query-b');
298	      await Future<void>.delayed(const Duration(milliseconds: 350));
299	    });
300	
301	    // Two separate ResourceLoading events on the stream — not collapsed
302	    // into one no-op by `Cubit.emit`'s own `==`-based skip.
303	    expect(emitted.whereType<ResourceLoading<List<Entry>>>(), hasLength(2));
304	  });
305	
306	  test(
307	    'I/O matrix: "Stale response" variant — an in-flight query discarded '
308	    'by clearing the field back to empty must never land once resolved',
309	    () async {
310	      fakeRepository.gated = true;
311	
312	      cubit.onQueryChanged('ansiedade');
313	      await Future<void>.delayed(const Duration(milliseconds: 350));
314	      expect(cubit.state, isA<ResourceLoading<List<Entry>>>());
315	
316	      cubit.onQueryChanged('');
317	      expect(cubit.state, const ResourceIdle<List<Entry>>());
318	
319	      fakeRepository.resolve(0, right([_entry('stale')]));
320	      await Future<void>.delayed(Duration.zero);
321	      expect(cubit.state, const ResourceIdle<List<Entry>>());
322	    },
323	  );
324	
325	  test('close() while a search is in flight never throws (emit-after-close '
326	      'guard, mirrors MeusRegistrosCubit.loadFirstPage)', () async {
327	    fakeRepository.gated = true;
328	
329	    cubit.onQueryChanged('ansiedade');
330	    await Future<void>.delayed(const Duration(milliseconds: 350));
331	    await cubit.close();
332	
333	    fakeRepository.resolve(0, right([_entry('e1')]));
334	    await Future<void>.delayed(Duration.zero);
335	    // No exception means the generation/isClosed guard held.
336	  });
337	
338	  group('spec-5-3: updateFilters()', () {
339	    test('Boundaries: "While idle: silent storage, no call" — updateFilters() '
340	        'with no active query stores the fields but never calls search()', () {
341	      cubit.updateFilters(source: EntrySource.audio);
342	
343	      expect(fakeRepository.searchCalls, isEmpty);
344	    });
345	
346	    test(
347	      'review finding: calling updateFilters() with the exact same '
348	      'source/dateFrom/dateTo already stored is a no-op during an active '
349	      'search — no redundant entries-search call, since nothing actually '
350	      'changed (e.g. MeusRegistrosScreen.initState()\'s own unconditional '
351	      'reset-to-null on every mount, when no filter was ever active)',
352	      () async {
353	        fakeRepository.queueSearch(right([_entry('e1')]));
354	        cubit.onQueryChanged('ansiedade');
355	        await Future<void>.delayed(const Duration(milliseconds: 350));
356	        expect(fakeRepository.searchCalls, ['ansiedade']);
357	
358	        // Same values already stored (both default to null) — must not
359	        // fire a second search() call.
360	        cubit.updateFilters();
361	        await Future<void>.delayed(Duration.zero);
362	
363	        expect(fakeRepository.searchCalls, ['ansiedade']);
364	      },
365	    );
366	
367	    test('review finding: updateFilters() retries even with no filter change '
368	        'when the last search landed in ResourceError — the no-op-when-'
369	        'unchanged guard must not strand the user with no way to recover '
370	        'other than editing the search text', () async {
371	      fakeRepository.queueSearch(
372	        left(const Failure.networkOffline(message: 'offline')),
373	      );
